#include <iostream>
using namespace std;

struct Node {
    char letter;
    Node* next;
};

void push(Node*& top, char c) {
    Node* n = new Node();
    n->letter = c;
    n->next = top;
    top = n;
}

char pop(Node*& top) {
    Node* old = top;
    char c = old->letter;
    top = top->next;
    delete old;
    return c;
}

int main() {
    char word[4] = {'H', 'E', 'A', 'P'};
    Node* top = nullptr;
    for (int i = 0; i < 4; i++) {
        push(top, word[i]);
    }
    while (top != nullptr) {
        cout << pop(top);
    }
    cout << endl;
    return 0;
}
